@import url('https://fonts.googleapis.com/css2?family=Montserrat:wght@400;600;700&family=inter:wght@400;600;700&family=Playfair+Display:wght@400;600;700&display=swap');

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #0F0F0F;
  font-family: "Montserrat", sans-serif;
}

#ad-320x480 {
  width: 320px;
  height: 480px;
  background: #1F3A1A;
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  align-items: center;
}

/* Botanical texture layer */
.botanical-bg {
  position: absolute;
  inset: 0;
  background-image: url('data:image/jpeg;base64,');
  background-size: cover;
  background-position: center bottom;
  opacity: 0.09;
  pointer-events: none;
  z-index: 0;
}

/* Particles */
.particles-container {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 1;
  overflow: hidden;
}

.particle {
  position: absolute;
  border-radius: 50%;
  opacity: 0;
  animation: floatParticle linear infinite;
}

@keyframes floatParticle {
  0%   { transform: translate(0, 0) scale(1);   opacity: 0; }
  10%  { opacity: 0.65; }
  80%  { opacity: 0.35; }
  100% { transform: translate(var(--tx), var(--ty)) scale(0.25); opacity: 0; }
}

/* Logo band */
.logo-band {
  position: relative;
  z-index: 10;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(245, 241, 230, 0.94);
  padding: 9px 16px 7px;
  flex-shrink: 0;
}

.logo-img {
  height: 28px;
  width: auto;
  display: block;
}

/* Eyebrow */
.eyebrow {
  position: relative;
  z-index: 10;
  font-family: "Montserrat", sans-serif;
  font-weight: 500;
  font-size: 9px;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: #C9D89A;
  margin-top: 8px;
  text-align: center;
  flex-shrink: 0;
}

/* Product hero */
.product-hero {
  position: relative;
  z-index: 10;
  width: 218px;
  height: 188px;
  margin-top: 6px;
  flex-shrink: 0;
  cursor: pointer;
  transition: transform 0.35s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.product-hero:hover,
.product-hero.tapped {
  transform: scale(1.05);
}

.product-halo {
  position: absolute;
  inset: -16px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(143, 183, 62, 0.24) 0%, rgba(143, 183, 62, 0) 70%);
  animation: haloBreath 3.2s ease-in-out infinite;
  pointer-events: none;
}

@keyframes haloBreath {
  0%, 100% { opacity: 0.55; transform: scale(0.90); }
  50%       { opacity: 1;    transform: scale(1.06); }
}

.product-img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  object-position: center;
  display: block;
  animation: kenBurns 14s ease-in-out infinite alternate;
  transform-origin: center center;
}

@keyframes kenBurns {
  0%   { transform: scale(1.00) translate(0px, 0px); }
  100% { transform: scale(1.07) translate(-4px, -3px); }
}

/* Text zone */
.text-zone {
  position: relative;
  z-index: 10;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  margin-top: 8px;
  padding: 0 16px;
  flex-shrink: 0;
}

/* Headline */
.headline {
  font-family: "Inter", sans-serif;
  font-weight: 700;
  font-size: 22px;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  color: #F5F1E6;
  text-align: center;
  line-height: 1.2;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  min-height: 54px;
}

.headline-word {
  display: inline-block;
  white-space: nowrap;
}

.headline-letter {
  display: inline-block;
  opacity: 0;
  transform: translateY(10px);
  animation: letterIn 0.45s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

@keyframes letterIn {
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Subhead */
.subhead {
  font-family: "Playfair Display", sans-serif;
  font-weight: 400;
  font-style: italic;
  font-size: 13px;
  color: #C9D89A;
  text-align: center;
  letter-spacing: 0.03em;
}

/* Badges */
.badges {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: center;
  margin-top: 2px;
}

.badge {
  font-family: "Montserrat", sans-serif;
  font-weight: 600;
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #1F3A1A;
  background: #C9D89A;
  border-radius: 3px;
  padding: 2px 7px;
}

.price {
  font-family: "Montserrat", sans-serif;
  font-weight: 500;
  font-size: 12px;
  color: #F5F1E6;
  letter-spacing: 0.04em;
}

/* CTA zone */
.cta-zone {
  position: relative;
  z-index: 10;
  margin-top: 10px;
  flex-shrink: 0;
}

.cta-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: #C9A961;
  color: #0F0F0F;
  text-decoration: none;
  border-radius: 4px;
  padding: 11px 38px;
  animation: ctaPulse 2.5s ease-in-out infinite;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.cta-btn:hover,
.cta-btn:active {
  transform: scale(1.06);
  animation-play-state: paused;
  box-shadow: 0 0 20px rgba(201, 169, 97, 0.75);
}

@keyframes ctaPulse {
  0%, 100% {
    box-shadow: 0 0 0px rgba(201, 169, 97, 0);
    transform: scale(1);
  }
  50% {
    box-shadow: 0 0 18px rgba(201, 169, 97, 0.65);
    transform: scale(1.025);
  }
}

.cta-label {
  font-family: "Montserrat", sans-serif;
  font-weight: 600;
  font-size: 13px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

/* Footer */
.ad-footer {
  position: relative;
  z-index: 10;
  margin-top: auto;
  padding-bottom: 14px;
  width: 100%;
  text-align: center;
  flex-shrink: 0;
}

.ad-footer span {
  font-family: "Montserrat", sans-serif;
  font-weight: 400;
  font-size: 8px;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  color: rgba(245, 241, 230, 0.40);
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  .particle,
  .product-img,
  .product-halo,
  .cta-btn,
  .headline-letter {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }
}

